P.QAUD = {"seeker":["¿Qué relación tiene este pasaje con mi vida de hoy?","Aún no practico la fe cristiana. ¿Qué significan estas palabras para mí?","¿Existe Dios de verdad? ¿Qué razones hay para creer?","¿Por qué dice la Biblia que todas las personas necesitan a Jesús?","Vivo con mucho estrés. ¿Qué ayuda práctica me ofrece la Biblia?","¿Qué significa aquí la palabra “pecado”? ¿Tiene algo que ver conmigo?","Los cristianos hablan siempre de la “gracia”. ¿Qué es, dicho con palabras sencillas?","Si quiero conocer más, ¿por dónde empiezo?"],"teen":["¿Qué relación tiene este pasaje con mi día a día, como el colegio, mis amigos y el celular?","Si este pasaje fuera un mensaje de Dios solo para mí, ¿qué diría?","Todos lo hacen. ¿Es raro que yo no lo haga? ¿Qué dice la Escritura?","¿Puedes explicar este pasaje con un videojuego o una película?","¿Qué tiene este pasaje de sorprendente o de poco conocido?","La presión de los exámenes es enorme. ¿Qué fuerza me da este pasaje?","Me cuesta perdonar a una persona. ¿Cómo me ayuda este pasaje?","¿De verdad me ve Dios? ¿Qué me hace merecedor de amor?"],"kid":["¿De qué trata esta historia? Cuéntamela, por favor.","¿Qué hizo Dios en esta historia?","¿Me ama el Señor Jesús? ¿Cómo lo sé?","¿Quién es el más valiente de esta historia? ¿Por qué?","¿Cómo puedo ser como las personas de esta historia?","Enséñame un versículo corto que pueda memorizar.","Me peleé con mi mejor amigo o amiga. ¿Qué haría el Señor Jesús?","¿Me enseñas una oración cortita?"]};
P.AUD2 = {"elder":{"q":["Con las palabras más sencillas, ¿qué dice este pasaje?","¿Qué consuelo da este pasaje a las personas mayores?","Mi cuerpo se va debilitando. ¿Cómo cuida Dios de mí?","A menudo siento soledad. ¿Qué me da este pasaje?","¿Cómo puedo transmitir mi fe a mis hijos y nietos?","Hay cosas que no logro soltar. ¿Cómo me enseña este pasaje a confiárselas al Señor?","Ya tengo mucha edad. ¿Qué más puedo hacer por Dios?","Escríbeme, por favor, una oración corta que pueda presentar al Señor."],"fu":["Salud","Soledad","Familia","Confianza","Esperanza","Oración"],"rw":["¡Terminaste todo el libro de {nm}!","Día tras día has llegado hasta aquí. Dios recuerda esta fidelidad, y es un ejemplo para quienes somos más jóvenes."],"res":["No te preocupes, vamos despacio. Si lo lees otra vez, el significado quedará más claro.","¡Muy bien! Recuerdas mucho de este capítulo.","¡Maravilloso! La Palabra de Dios vive en tu corazón."]},"single_parent":{"q":["Llevo la carga de la familia sin ayuda. ¿Qué consuelo me da este pasaje?","Estoy sin fuerzas y siento que les debo más a mis hijos. ¿Cómo me ve Dios?","¿Cómo cuida Dios de los huérfanos y las viudas, y qué significa eso para mí?","El dinero escasea muchísimo. ¿Qué me da este pasaje?","Mi hijo me responde mal y tiene emociones muy intensas. ¿Qué debo hacer?","No sé cómo decirle a mi hijo que su papá (o su mamá) no está con nosotros.","Siento una gran soledad. ¿Cómo puedo pedir ayuda a la iglesia o a mis hermanos en la fe?","Escríbeme, por favor, una oración corta que pueda rezar en cinco minutos."],"fu":["Cansancio","Hijos","Dinero","Pedir ayuda","Esperanza","Oración"],"rw":["¡Terminaste todo el libro de {nm}!","No es fácil seguir leyendo la Biblia mientras sacas adelante a tu familia en solitario. Dios ve cada paso que das, y está contigo."],"res":["No te preocupes, has hecho un gran esfuerzo. Vuelve a leerlo cuando tengas tiempo.","¡Muy bien! Recuerdas mucho a pesar de tus días tan ocupados.","¡Maravilloso! La Palabra de Dios te sostiene."]},"single":{"q":["Como persona soltera, ¿qué me dice este pasaje?","Siento soledad. ¿Qué me da este pasaje?","¿Quién soy en Cristo y cuánto valgo?","¿Cómo confío en Dios mientras espero?","¿Qué sabiduría ofrece la Biblia sobre las relaciones?","¿Cómo pueden usarse para Dios el tiempo y las fuerzas de una persona soltera?","¿Cómo construyo buenas relaciones en la iglesia y con mis amigos?","Escríbeme, por favor, una oración corta para una persona soltera."],"fu":["Soledad","Identidad","Espera","Relaciones","Propósito de vida","Oración"],"rw":["¡Terminaste todo el libro de {nm}!","Has seguido adelante por tu cuenta, y ante Dios tus días son plenos y amados."],"res":["No te preocupes, vamos despacio. Si lo lees otra vez, el significado quedará más claro.","¡Muy bien! Captaste lo esencial de este capítulo.","¡Excelente! Eres constante, y la Palabra de Dios echa raíces en ti."]},"parent":{"q":["Como padre o madre, ¿qué me recuerda este pasaje?","Mi hijo no me escucha y tiene emociones muy intensas. ¿Cómo debo responder?","¿Cómo equilibro la disciplina y la gracia?","¿Cómo puedo comunicarme bien con un hijo adolescente?","Me enojo a menudo con mi hijo y luego me siento culpable. ¿Qué hago?","¿Cómo guío a mi hijo para que conozca a Dios y no solo vaya a la iglesia?","Mi pareja y yo no coincidimos en cómo criar a nuestro hijo. ¿Qué dice este pasaje?","Escríbeme, por favor, una oración corta de bendición para mi hijo."],"fu":["Diálogo","Disciplina","Conciencia","Pareja","Fe","Oración"],"rw":["¡Terminaste todo el libro de {nm}!","Leer la Escritura cada día en medio del ajetreo de criar hijos es el mejor ejemplo que puedes darles."],"res":["No te preocupes, vamos despacio. Vuelve a leerlo cuando tengas ocasión.","¡Muy bien! Captaste lo esencial de este capítulo.","¡Maravilloso! La Palabra de Dios echa raíces en tu hogar."]},"couple":{"q":["Como matrimonio, ¿qué nos dice este pasaje?","Después de cada discusión nos enfriamos. ¿Cómo puede uno de nosotros dar el primer paso para reconciliarnos?","¿Cómo puedo expresar lo que siento para que mi pareja me escuche?","Mi pareja me hirió. ¿De verdad tengo que perdonar?","No coincidimos en el dinero ni en las tareas del hogar. ¿Qué hacemos?","¿Cómo podemos orar juntos y acercarnos a Dios como pareja?","Nos hemos distanciado por el ajetreo de la vida. ¿Cómo volvemos a acercarnos?","Escríbenos, por favor, una oración corta de bendición para nuestro matrimonio."],"fu":["Diálogo","Perdón","Cercanía","Un solo corazón","Lectura en pareja","Oración"],"rw":["¡Terminaron juntos todo el libro de {nm}!","Una pareja que se acerca junta a la Palabra de Dios se apoya en un cimiento firme."],"res":["No se preocupen, vamos despacio. Vuelvan a leerlo juntos una de estas noches.","¡Muy bien! Los dos captaron lo esencial de este capítulo.","¡Maravilloso! La Palabra de Dios echa raíces en su matrimonio."]},"pastor":{"q":["En el servicio al Señor, ¿qué me dice este pasaje?","Ayúdame a encontrar un bosquejo de mensaje y un punto de partida para este pasaje.","Estoy al borde del agotamiento. ¿Qué consuelo me da este pasaje?","¿Cómo enfrento las críticas y los malentendidos dentro de la iglesia?","¿Qué dice este pasaje sobre cómo guiar a un equipo con un mismo corazón?","¿Cómo cuido mi relación personal con Dios en medio de un ministerio tan ocupado?","¿Cómo pastoreo a los débiles, a los heridos y a quienes se alejaron de la iglesia?","Escríbeme, por favor, una oración corta de intercesión por la iglesia y mis colaboradores."],"fu":["Mensaje","Pastoreo","Equipo","Descanso","Guerra espiritual","Intercesión"],"rw":["¡Terminaste todo el libro de {nm}!","Permanecer cerca de la Palabra de Dios en medio de un ministerio ajetreado es la raíz más profunda del pastoreo."],"res":["No te preocupes, vamos despacio. Vuelve a leerlo cuando tengas ocasión.","¡Muy bien! Captaste lo esencial de este capítulo.","¡Maravilloso! La Palabra de Dios alimenta primero al pastor y luego fluye hacia el rebaño."]}};
